    <script>
      $(document).ready(function () {
        // 隐藏加载动画，显示主内容
        setTimeout(function () {
          $('#loadingSpinner').fadeOut(300);
          $('#storyAssistantContainer').fadeIn(500);
          $('body').addClass('loaded');
        }, 800);

        // 错误处理
        window.addEventListener('error', function (e) {
          const errorMessage = e.error?.message || e.message || '';

          // 忽略常见的无害 ResizeObserver 错误
          if (errorMessage.includes('ResizeObserver loop')) {
            console.log('📏 忽略ResizeObserver循环警告（这是正常的）');
            return;
          }

          console.error('剧情小助手错误:', e.error);
          console.error('错误详情:', {
            message: errorMessage,
            filename: e.filename,
            lineno: e.lineno,
            colno: e.colno,
            stack: e.error?.stack,
          });

          // 显示详细错误信息给用户（开发环境）
          const $feedback = $('#feedbackMessage');
          if ($feedback.length) {
            $feedback.text(`错误: ${errorMessage}`).addClass('show');
            setTimeout(() => {
              $feedback.removeClass('show');
            }, 5000); // 延长显示时间以便查看
          }
        });

        // 添加键盘快捷键支持
        $(document).on('keydown', function (e) {
          // 确保不在输入框中
          if ($(e.target).is('input, textarea')) {
            return;
          }

          switch (e.keyCode) {
            case 37: // 左箭头 - 返回上步
              e.preventDefault();
              $('#prevBtn').click();
              break;
            case 39: // 右箭头 - 继续剧情
              e.preventDefault();
              $('#nextBtn').click();
              break;
            case 76: // L键 - 打开/关闭列表
              e.preventDefault();
              $('#listBtn').click();
              break;
            case 27: // ESC键 - 关闭列表
              e.preventDefault();
              if ($('#storyListPanel').is(':visible')) {
                $('#closeListBtn').click();
              }
              break;
          }
        });

        // 触摸设备支持
        let touchStartX = 0;
        let touchEndX = 0;

        $('.story-control-panel').on('touchstart', function (e) {
          touchStartX = e.originalEvent.changedTouches[0].screenX;
        });

        $('.story-control-panel').on('touchend', function (e) {
          touchEndX = e.originalEvent.changedTouches[0].screenX;
          handleSwipe();
        });

        function handleSwipe() {
          const minSwipeDistance = 50;
          const swipeDistance = touchEndX - touchStartX;

          if (Math.abs(swipeDistance) > minSwipeDistance) {
            if (swipeDistance > 0) {
              // 向右滑动 - 返回上步
              $('#prevBtn').click();
            } else {
              // 向左滑动 - 继续剧情
              $('#nextBtn').click();
            }
          }
        }

        // 面板展开收缩全局处理函数
        window.expandPlugin = expandPlugin;
        window.collapsePlugin = collapsePlugin;

        // 点击面板外部关闭剧情列表
        $('#storyListPanel').on('click', function (e) {
          if (e.target === this) {
            $('#closeListBtn').click();
          }
        });

        console.log('剧情小助手页面初始化完成');
        console.log('支持键盘快捷键: ← (返回上步) → (继续剧情), L (列表), ESC (关闭)');
        console.log('支持触摸手势: 左右滑动控制剧情进度');

        // iframe 环境适配
        initIframeAdaptation();
      });

      /**
       * iframe 环境适配函数
       */
      function initIframeAdaptation() {
        // 检测是否在iframe中
        const isInIframe = window.self !== window.top;

        if (isInIframe) {
          console.log('🖼️ 检测到iframe环境，启用适配模式');

          // 添加iframe标识类
          document.body.classList.add('in-iframe');

          // 监听iframe尺寸变化并通知父页面（使用防抖避免循环）
          let lastHeight = 0;
          let resizeTimeout = null;

          const resizeObserver = new ResizeObserver(entries => {
            try {
              // 清除之前的timeout
              if (resizeTimeout) {
                clearTimeout(resizeTimeout);
              }

              // 使用防抖，避免频繁调用
              resizeTimeout = setTimeout(() => {
                try {
                  const currentHeight = document.body.scrollHeight;
                  // 只有当高度真正变化时才通知
                  if (Math.abs(currentHeight - lastHeight) > 5) {
                    // 5px容差
                    lastHeight = currentHeight;
                    notifyParentHeightChange();
                  }
                } catch (error) {
                  // 静默处理高度通知错误
                  console.log('📏 高度通知错误（已忽略）:', error.message);
                }
              }, 100); // 100ms防抖延迟
            } catch (error) {
              // 静默处理ResizeObserver错误
              console.log('📏 ResizeObserver回调错误（已忽略）:', error.message);
            }
          });

          // 开始观察body尺寸变化，并捕获可能的错误
          try {
            resizeObserver.observe(document.body);
          } catch (e) {
            console.warn('ResizeObserver初始化失败:', e.message);
          }

          // 禁用可能影响iframe的功能
          disableProblematicFeatures();
        } else {
          console.log('🖥️ 独立页面环境');
        }
      }

      /**
       * 通知父页面iframe高度变化
       */
      function notifyParentHeightChange() {
        if (window.self !== window.top) {
          try {
            const height = document.body.scrollHeight;
            window.parent.postMessage(
              {
                type: 'story-assistant-resize',
                height: height,
              },
              '*',
            );
            console.log(`📏 通知父页面高度变化: ${height}px`);
          } catch (e) {
            console.log('📏 无法通知父页面高度变化:', e.message);
          }
        }
      }

      // 暴露到全局以便其他模块调用
      window.notifyParentHeightChange = notifyParentHeightChange;

      /**
       * 展开插件（显示面板）
       */
      function expandPlugin() {
        document.body.classList.add('plugin-expanded');
        document.body.style.overflow = 'auto';
        setTimeout(notifyParentHeightChange, 350); // 等待动画完成
      }

      /**
       * 收缩插件（隐藏面板）
       */
      function collapsePlugin() {
        document.body.classList.remove('plugin-expanded');
        document.body.style.overflow = 'hidden';
        setTimeout(notifyParentHeightChange, 350); // 等待动画完成
      }

      /**
       * 禁用可能在iframe中有问题的功能
       */
      function disableProblematicFeatures() {
        // 在iframe中禁用键盘快捷键（可能与父页面冲突）
        $(document).off('keydown');
        console.log('⌨️ 已禁用键盘快捷键（iframe模式）');
      }

      // 插件API - 供外部调用
      window.StoryAssistant = {
        version: '1.0.0',

        // 获取当前剧情
        getCurrentStory: function () {
          return window.getCurrentStory ? window.getCurrentStory() : null;
        },

        // 跳转到指定剧情
        goToStory: function (index) {
          return window.goToStory ? window.goToStory(index) : false;
        },

        // 设置剧情数据
        setStoryData: function (stories) {
          return window.setStoryData ? window.setStoryData(stories) : false;
        },

        // 获取插件状态
        getStatus: function () {
          return {
            ready: typeof window.getCurrentStory === 'function',
            version: this.version,
            timestamp: new Date().toISOString(),
          };
        },

        // 手动展开插件
        expand: function () {
          expandPlugin();
        },

        // 手动收缩插件
        collapse: function () {
          collapsePlugin();
        },
      };

      /**
       * 父页面监听iframe高度变化示例代码:
       *
       * window.addEventListener('message', function(event) {
       *   if (event.data.type === 'story-assistant-resize') {
       *     const iframe = document.getElementById('story-assistant-iframe');
       *     if (iframe) {
       *       iframe.style.height = event.data.height + 'px';
       *     }
       *   }
       * });
       */

      console.log('剧情小助手 API 已准备就绪', window.StoryAssistant.getStatus());
    </script>

